import React from 'react';
import { Link, useLocation } from 'react-router-dom';

function Navbar({ user, onLogout }) {
  const location = useLocation();

  const navStyle = {
    background: '#1e293b',
    padding: '0.8rem 2rem',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
  };

  const logoStyle = {
    color: 'white',
    fontSize: '1.1rem',
    fontWeight: '700',
    textDecoration: 'none'
  };

  const linkStyle = (path) => ({
    color: location.pathname === path ? '#60a5fa' : '#94a3b8',
    textDecoration: 'none',
    marginRight: '1.5rem',
    fontSize: '0.95rem',
    fontWeight: '500'
  });

  const userStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '1rem'
  };

  return (
    <nav style={navStyle}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
        <Link to="/" style={logoStyle}>🏫 StaffMeet</Link>
        <Link to="/" style={linkStyle('/')}>Dashboard</Link>
        <Link to="/meetings" style={linkStyle('/meetings')}>Meetings</Link>
        {user.role === 'admin' && (
          <Link to="/create-meeting" style={linkStyle('/create-meeting')}>+ New Meeting</Link>
        )}
        {user.role === 'admin' && (
          <Link to="/manage-users" style={linkStyle('/manage-users')}>Manage Users</Link>
        )}
      </div>

      <div style={userStyle}>
        <span style={{ color: '#94a3b8', fontSize: '0.9rem' }}>
          👤 {user.name}
          <span style={{
            background: user.role === 'admin' ? '#7c3aed' : '#0f766e',
            color: 'white',
            padding: '2px 8px',
            borderRadius: '10px',
            fontSize: '0.7rem',
            marginLeft: '8px'
          }}>
            {user.role}
          </span>
        </span>
        <button
          onClick={onLogout}
          style={{
            background: 'transparent',
            border: '1px solid #475569',
            color: '#94a3b8',
            padding: '0.3rem 0.8rem',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.85rem'
          }}
        >
          Logout
        </button>
      </div>
    </nav>
  );
}

export default Navbar;
